// Philippine provinces / cities / barangays, served from public/ph-address
// (generated by tools/build-ph-address.py). Entries are [code, name].
export type Place = [code: string, name: string];

let placesPromise: Promise<{ provinces: Place[]; cities: Record<string, Place[]> }> | null = null;
const barangayPromises: Record<string, Promise<Record<string, Place[]>>> = {};

function load<T>(url: string): Promise<T> {
  return fetch(url).then((r) => {
    if (!r.ok) throw new Error(`Failed to load ${url}`);
    return r.json();
  });
}

export function loadPlaces() {
  placesPromise ??= load<{ provinces: Place[]; cities: Record<string, Place[]> }>('/ph-address/places.json').catch((e) => {
    placesPromise = null; // allow a retry
    throw e;
  });
  return placesPromise;
}

// Barangays of one city; the file holds the whole province, cached per province
export async function loadBarangays(cityCode: string): Promise<Place[]> {
  const provinceCode = cityCode.slice(0, 4);
  barangayPromises[provinceCode] ??= load<Record<string, Place[]>>(`/ph-address/barangays/${provinceCode}.json`).catch((e) => {
    delete barangayPromises[provinceCode];
    throw e;
  });
  return (await barangayPromises[provinceCode])[cityCode] ?? [];
}
